/* Tooltips remain real text, keyboard-readable and bounded to the viewport. */
(() => {
  const tooltip = document.createElement('div');
  tooltip.id = 'refined-tooltip';
  tooltip.className = 'refined-tooltip';
  tooltip.setAttribute('role', 'tooltip');
  tooltip.hidden = true;
  document.body.append(tooltip);
  let trigger = null;
  function hide() {
    if (trigger) {
      const ids = (trigger.getAttribute('aria-describedby') || '').split(/\s+/).filter(id => id && id !== tooltip.id);
      if (ids.length) trigger.setAttribute('aria-describedby', ids.join(' '));
      else trigger.removeAttribute('aria-describedby');
    }
    trigger = null;
    tooltip.hidden = true;
  }
  function show(next) {
    if (!next || !next.isConnected || next.closest('[inert]') || !document.getElementById('control-popover')?.hidden) return;
    hide();
    trigger = next;
    tooltip.textContent = next.dataset.tooltip;
    tooltip.hidden = false;
    const rect = next.getBoundingClientRect();
    tooltip.style.left = Math.max(8, Math.min(rect.left + rect.width / 2 - tooltip.offsetWidth / 2, innerWidth - tooltip.offsetWidth - 8)) + 'px';
    tooltip.style.top = (rect.bottom + tooltip.offsetHeight + 12 < innerHeight ? rect.bottom + 8 : Math.max(8, rect.top - tooltip.offsetHeight - 8)) + 'px';
    const ids = (next.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean);
    next.setAttribute('aria-describedby', [...new Set([...ids, tooltip.id])].join(' '));
  }
  function cleanTitles() {
    document.querySelectorAll('[data-tooltip][title]').forEach(el => el.removeAttribute('title'));
    if (trigger && !trigger.isConnected) hide();
  }
  cleanTitles();
  new MutationObserver(cleanTitles).observe(document.getElementById('app'), { childList: true, subtree: true });
  document.addEventListener('focusin', event => show(event.target.closest('[data-tooltip]')));
  document.addEventListener('focusout', event => { if (event.target === trigger) hide(); });
  document.addEventListener('pointerover', event => {
    const next = event.target.closest('[data-tooltip]');
    if (next && next !== trigger && matchMedia('(hover: hover)').matches) show(next);
  });
  document.addEventListener('pointerout', event => { if (trigger && !trigger.contains(event.relatedTarget)) hide(); });
  document.addEventListener('pointerdown', hide, true);
  document.addEventListener('keydown', event => { if (event.key === 'Escape') hide(); }, true);
  document.addEventListener('scroll', hide, true);
  window.addEventListener('resize', hide);
})();
